task.vi:
Truyền theo giá trị (pass-by-value) là gì? Truyền theo tham chiếu (pass-by-reference) là gì? Cho biết kết quả in ra màn hình của các đoạn mã sau:
(a)
```cpp
#include <iostream>
using namespace std;
void maxValue(int value1, int value2, int max) {
  if (value1 > value2) max = value1;
  else max = value2;
}
int main() {
  int max = 0;
  maxValue(1, 2, max);
  cout << "max is " << max << endl;
  return 0;
}
```
(b)
```cpp
#include <iostream>
using namespace std;
void maxValue(int value1, int value2, int& max) {
  if (value1 > value2) max = value1;
  else max = value2;
}
int main() {
  int max = 0;
  maxValue(1, 2, max);
  cout << "max is " << max << endl;
  return 0;
}
```
(c)
```cpp
#include <iostream>
using namespace std;
void f(int i, int num) {
  for (int j = 1; j <= i; j++) {
    cout << num << " ";
    num *= 2;
  }
  cout << endl;
}
int main() {
  int i = 1;
  while (i <= 6) {
    f(i, 2);
    i++;
  }
  return 0;
}
```
(d)
```cpp
#include <iostream>
using namespace std;
void f(int& i, int num) {
  for (int j = 1; j <= i; j++) {
    cout << num << " ";
    num *= 2;
  }
  cout << endl;
}
int main() {
  int i = 1;
  while (i <= 6) {
    f(i, 2);
    i++;
  }
  return 0;
}
```

