#include <iostream>

void swapValues(int& n1, int& n2) {
    int temp = n1;
    n1 = n2;
    n2 = temp;
}

void maxValueRef(int val1, int val2, int& maxOut) {
    if (val1 > val2) {
        maxOut = val1;
    } else {
        maxOut = val2;
    }
}

int main() {
    int num1 = 10;
    int num2 = 25;
    std::cout << "Before swap: num1=" << num1 << ", num2=" << num2 << "\n";
    swapValues(num1, num2);
    std::cout << "After swap: num1=" << num1 << ", num2=" << num2 << "\n";

    int maxResult = 0;
    maxValueRef(num1, num2, maxResult);
    std::cout << "Computed max: " << maxResult << "\n";

    return 0;
}

#include <iostream>
#include <utility>

// Corrected Check Point 6.24: modifying the references directly
void minMaxRef(double a, double b, double& minOut, double& maxOut) {
    if (a < b) {
        minOut = a;
        maxOut = b;
    } else {
        minOut = b;
        maxOut = a;
    }
}

// Modern C++17 approach using structured bindings
std::pair<double, double> getMinMax(double a, double b) {
    return (a < b) ? std::make_pair(a, b) : std::make_pair(b, a);
}

int main() {
    double a = 5.0;
    double b = 6.0;
    double minVal = 0.0;
    double maxVal = 0.0;

    minMaxRef(a, b, minVal, maxVal);
    std::cout << "min is " << minVal << " and max is " << maxVal << "\n";

    // C++17 structured binding demonstration
    auto [mn, mx] = getMinMax(a, b);
    std::cout << "C++17 structured binding: min=" << mn << ", max=" << mx << "\n";

    return 0;
}
